/** Twelve type tokens (+ captionWrap, body1Italic, badgeCount). Font family is applied by EqualTheme. */
object EqualTypeTokens {
    private val T = (-0.026).em      // system default
    private val T_11 = 0.08.em     // uppercase at 11sp
    private val T_10 = 0.06.em     // uppercase at 10sp
    private const val TNUM = "tnum"

    val headline = TextStyle(fontSize = 24.sp, lineHeight = 32.sp, fontWeight = FontWeight.W500, letterSpacing = T)
    val title = TextStyle(fontSize = 20.sp, lineHeight = 28.sp, fontWeight = FontWeight.W500, letterSpacing = T)
    val subheading = TextStyle(fontSize = 16.sp, lineHeight = 24.sp, fontWeight = FontWeight.W500, letterSpacing = T)
    val bodyLarge = TextStyle(fontSize = 16.sp, lineHeight = 24.sp, fontWeight = FontWeight.W400, letterSpacing = T)
    val body2 = TextStyle(fontSize = 14.sp, lineHeight = 22.sp, fontWeight = FontWeight.W500, letterSpacing = T)
    val body1 = TextStyle(fontSize = 14.sp, lineHeight = 22.sp, fontWeight = FontWeight.W400, letterSpacing = T)
    val body1Italic = TextStyle(fontSize = 14.sp, lineHeight = 22.sp, fontWeight = FontWeight.W400, letterSpacing = T, fontStyle = FontStyle.Italic)
    val button = TextStyle(fontSize = 14.sp, lineHeight = 20.sp, fontWeight = FontWeight.W500, letterSpacing = T)
    val buttonSmall = TextStyle(fontSize = 12.sp, lineHeight = 16.sp, fontWeight = FontWeight.W500, letterSpacing = T)
    val caption = TextStyle(fontSize = 12.sp, lineHeight = 16.sp, fontWeight = FontWeight.W500, letterSpacing = T)
    val captionWrap = TextStyle(fontSize = 12.sp, lineHeight = 18.sp, fontWeight = FontWeight.W400, letterSpacing = T)
    val micro = TextStyle(fontSize = 12.sp, lineHeight = 16.sp, fontWeight = FontWeight.W500, letterSpacing = T, fontFeatureSettings = TNUM)
    val overline = TextStyle(fontSize = 11.sp, lineHeight = 16.sp, fontWeight = FontWeight.W500, letterSpacing = T_11) // uppercase the string, not the renderer
    val badge = TextStyle(fontSize = 10.sp, lineHeight = 12.sp, fontWeight = FontWeight.W500, letterSpacing = T_10) // uppercase the string, not the renderer
    val badgeCount = TextStyle(fontSize = 10.sp, lineHeight = 12.sp, fontWeight = FontWeight.W500, letterSpacing = T, fontFeatureSettings = TNUM)
}

